454	fn rsplit_delimiter<'s, 'o>(
455	    value: Result<&'s str, &'o OsStr>,
456	    delimiter: Option<char>,
457	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
458	    let delimiter = delimiter?;
459	    let value = value.ok()?;
460	    let pos = value.rfind(delimiter)?;
461	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
462	    Some((Some(prefix), Ok(value)))
463	}
