476	fn complete_candidates_str(
477	    value: &str,
478	    mut values: Vec<CompletionCandidate>,
479	) -> Vec<CompletionCandidate> {
480	    debug!("complete_candidates_str: value={value:?}");
481	
482	    values.retain(|comp| comp.get_value().starts_with(value));
483	    values
484	}
