486	fn complete_value_candidates_str(
487	    value: &str,
488	    completer: &dyn ValueCandidates,
489	) -> Vec<CompletionCandidate> {
490	    debug!("complete_value_candidates_str: value={value:?}");
491	
492	    complete_candidates_str(value, completer.candidates())
493	}
