495	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
496	    debug!(
497	        "complete_subcommand: cmd={:?}, value={:?}",
498	        cmd.get_name(),
499	        value
500	    );
501	
502	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
503	        .into_iter()
504	        .filter(|x| x.get_value().starts_with(value))
505	        .collect();
506	    if cmd.is_allow_external_subcommands_set() {
507	        let external_completer = cmd.get::<SubcommandCandidates>();
508	        if let Some(completer) = external_completer {
509	            scs.extend(complete_value_candidates_str(
510	                value,
511	                completer.value_candidates(),
512	            ));
513	        }
514	    }
515	
516	    scs.dedup();
517	    scs
518	}
