    for line in [
        &["tool", "--json", "r", "--text", ""][..],
        &["tool", "--js", "r", "--txt", ""][..],
        &["tool", "--yaml", "run", "--binary", ""][..],
        &["tool", "--output", "file", "r", "--bin", ""][..],
    ] {
        assert_eq!(group_values(line), ["job", "log"], "{line:?}");
    }
}

